$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Definition
Set-Location $scriptDir
Write-Host "Creation des fichiers racine dans : $scriptDir" -ForegroundColor Cyan

# docker-compose.yml
[System.IO.File]::WriteAllBytes("$scriptDir\docker-compose.yml", [System.Convert]::FromBase64String(""))

# docker-stack.yml
[System.IO.File]::WriteAllBytes("$scriptDir\docker-stack.yml", [System.Convert]::FromBase64String(""))

# .gitlab-ci.yml
[System.IO.File]::WriteAllBytes("$scriptDir\.gitlab-ci.yml", [System.Convert]::FromBase64String(""))

# .env.example
[System.IO.File]::WriteAllBytes("$scriptDir\.env.example", [System.Convert]::FromBase64String(""))

# .gitignore
[System.IO.File]::WriteAllBytes("$scriptDir\.gitignore", [System.Convert]::FromBase64String("LmVudgoqLnB5YwpfX3B5Y2FjaGVfXy8KYXBwL3VwbG9hZHMvCioudGFyLmd6Ci5EU19TdG9yZQo="))

# README.md
[System.IO.File]::WriteAllBytes("$scriptDir\README.md", [System.Convert]::FromBase64String(""))

Write-Host "Fichiers crees :" -ForegroundColor Green
Get-ChildItem -File | Select-Object Name